var json = JSON.parse(result);
var content = json.data[0].content;
if(content && content.startsWith('https://')) {
    // 如果是视频链接
    if(book.durChapterIndex == chapter.index) {
        java.startBrowser(content.replace(/\\/g, ''), chapter.title);
        java.toast('正在加载视频\n视频加载较慢，请耐心等待');
    }
    result = '【刷新正文】播放\n✅直链:\n' + content;
} else {
    result = content;
}
result

searchUrl:
@js:
(function() {
    var sourceVal = '全部';
    try {
        var userSource = source.getVariable();
        if (userSource != null && String(userSource).length > 0) {
            // 解析JSON格式的变量
            var userObj = JSON.parse(userSource);
            if (userObj && userObj[0] && userObj[0].host) {
                sourceVal = userObj[0].host;
            }
        }
    } catch (e) {
        java.log('获取用户来源失败，使用默认值');
    }
    return getHost() + '/search?q={{key}}&source=' + encodeURIComponent(sourceVal);
})();

